import { useEffect, useState } from 'react';
import { UserPlus } from 'lucide-react';
import Alert from '../../../components/ui/Alert.jsx';
import Button from '../../../components/ui/Button.jsx';
import Drawer from '../../../components/ui/Drawer.jsx';
import Input from '../../../components/ui/Input.jsx';
import { createUser, updateUser } from '../../../services/users.service.js';

export default function UserFormDrawer({ open, onClose, onSaved, user, roles }) {
  const isEditing = Boolean(user);
    const [fullName, setFullName] = useState('');
      const [email, setEmail] = useState('');
        const [password, setPassword] = useState('');
          const [roleCode, setRoleCode] = useState('STAFF');
            const [isActive, setIsActive] = useState(true);
              const [error, setError] = useState('');
                const [saving, setSaving] = useState(false);

                  useEffect(() => {
                      if (!open) {
                            return;
                                }
                                    setFullName(user?.fullName || '');
                                        setEmail(user?.email || '');
                                            setPassword('');
                                                setRoleCode(user?.roleCode || 'STAFF');
                                                    setIsActive(user ? user.isActive : true);
                                                        setError('');
                                                          }, [open, user]);

                                                            const handleSubmit = async (event) => {
                                                                event.preventDefault();

                                                                    if (fullName.trim().length < 2) {
                                                                          setError('Enter the staff member’s full name.');
                                                                                return;
                                                                                    }
                                                                                        if (!isEditing && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
                                                                                              setError('Enter a valid email address.');
                                                                                                    return;
                                                                                                        }
                                                                                                            if (!isEditing && password.length < 8) {
                                                                                                                  setError('The temporary password must be at least 8 characters.');
                                                                                                                        return;
                                                                                                                            }

                                                                                                                                setSaving(true);
                                                                                                                                    setError('');
                                                                                                                                        try {
                                                                                                                                              const result = isEditing
                                                                                                                                                      ? await updateUser(user.id, {
                                                                                                                                                                  fullName: fullName.trim(),
                                                                                                                                                                              roleCode,
                                                                                                                                                                                          isActive
                                                                                                                                                                                                    })
                                                                                                                                                                                                            : await createUser({
                                                                                                                                                                                                                        fullName: fullName.trim(),
                                                                                                                                                                                                                                    email: email.trim(),
                                                                                                                                                                                                                                                password,
                                                                                                                                                                                                                                                            roleCode
                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                            onSaved(result, isEditing);
                                                                                                                                                                                                                                                                                } catch (submitError) {
                                                                                                                                                                                                                                                                                      setError(submitError.message || 'The staff account could not be saved.');
                                                                                                                                                                                                                                                                                          } finally {
                                                                                                                                                                                                                                                                                                setSaving(false);
                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                            <Drawer
                                                                                                                                                                                                                                                                                                                  open={open}
                                                                                                                                                                                                                                                                                                                        onClose={onClose}
                                                                                                                                                                                                                                                                                                                              title={isEditing ? `Edit ${user.fullName}` : 'Add staff account'}
                                                                                                                                                                                                                                                                                                                                    subtitle={
                                                                                                                                                                                                                                                                                                                                            isEditing
                                                                                                                                                                                                                                                                                                                                                      ? 'Changing the role signs this person out of all devices'
                                                                                                                                                                                                                                                                                                                                                                : 'They must change the temporary password at first login'
                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                <form onSubmit={handleSubmit} className="space-y-4" noValidate>
                                                                                                                                                                                                                                                                                                                                                                                        {error ? <Alert tone="error">{error}</Alert> : null}

                                                                                                                                                                                                                                                                                                                                                                                                <Input
                                                                                                                                                                                                                                                                                                                                                                                                          label="Full name"
                                                                                                                                                                                                                                                                                                                                                                                                                    name="userFullName"
                                                                                                                                                                                                                                                                                                                                                                                                                              value={fullName}
                                                                                                                                                                                                                                                                                                                                                                                                                                        onChange={(event) => setFullName(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder="Adaeze Okafor"
                                                                                                                                                                                                                                                                                                                                                                                                                                                          />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {isEditing ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="rounded-lg bg-sand-50 px-3 py-2 text-xs text-primary-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Email: <span className="font-semibold">{user.email}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label="Email address"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name="userEmail"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        type="email"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(event) => setEmail(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="name@healthcentre.local"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {!isEditing ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            label="Temporary password"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name="userPassword"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    type="password"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value={password}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(event) => setPassword(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="At least 8 characters"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    hint="Share this once; they are forced to replace it."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label className="field-label" htmlFor="user-role">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Role
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    id="user-role"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value={roleCode}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(event) => setRoleCode(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="field"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {(roles.length > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? roles
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            { code: 'STAFF', name: 'Staff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              { code: 'ADMINISTRATOR', name: 'Administrator' }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ).map((role) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option key={role.code} value={role.code}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {role.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {isEditing ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label className="flex items-center gap-2 rounded-lg border border-sand-200 px-3 py-2 text-sm text-primary-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="checkbox"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              checked={isActive}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(event) => setIsActive(event.target.checked)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="h-4 w-4 rounded border-sand-300 text-primary-600"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Account is active and can sign in
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex flex-col gap-2 border-t border-sand-200 pt-4 sm:flex-row-reverse">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Button type="submit" loading={saving} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <UserPlus className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {saving ? 'Saving' : isEditing ? 'Save changes' : 'Create account'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Button type="button" variant="outline" onClick={onClose} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Cancel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Drawer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }